INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Verzeichnis von Verarbeitungstätigkeiten für jedes Unternehmen Pflicht?', 2, '[{"text": "Nein", "correct": true, "because": "Kleine Unternehmen unter 250 Mitarbeitern ausgenommen, wenn kein Risiko"}, {"text": "Ja", "correct": false, "because": "Ausnahmen bei geringem Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Verzeichnis von Verarbeitungstätigkeiten?', 3, '[{"text": "Dokumentation", "correct": true, "because": "Übersicht über Datenverarbeitung"}, {"text": "Performance-Steigerung", "correct": false, "because": "Nicht datenschutzrelevant"}, {"text": "Kostensenkung", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Angaben gehören in ein Verzeichnis von Verarbeitungstätigkeiten?', 5, '[{"text": "Zweck der Verarbeitung", "correct": true, "because": "Erforderlich gemäß DSGVO"}, {"text": "Kategorien personenbezogener Daten", "correct": true, "because": "Zeigt, was verarbeitet wird"}, {"text": "Farbschema der Datenbank", "correct": false, "because": "Irrelevant"}, {"text": "Servergeschwindigkeit", "correct": false, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Verzeichnis dient der Nachweispflicht. b) Es ist nur für interne Zwecke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch für Behörden einsehbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Verzeichnis von Verarbeitungstätigkeiten?', 4, '[{"text": "Empfänger der Daten", "correct": false, "because": "Muss dokumentiert werden"}, {"text": "Löschfristen", "correct": false, "because": "Teil der DSGVO-Anforderung"}, {"text": "UI-Design", "correct": true, "because": "Kein Dokumentationsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Verzeichnis auch technische Maßnahmen enthält?', 2, '[{"text": "Ja", "correct": true, "because": "Sicherheitsmaßnahmen sind erforderlich"}, {"text": "Nein", "correct": false, "because": "Teil der Dokumentation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Information muss ich im Verzeichnis angeben?', 3, '[{"text": "Verantwortlicher", "correct": true, "because": "Pflicht gemäß DSGVO"}, {"text": "Datenbankgröße", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für ein Verzeichnis essenziell?', 5, '[{"text": "Datenkategorien", "correct": true, "because": "Zeigt Verarbeitungsumfang"}, {"text": "Übermittlung an Drittländer", "correct": true, "because": "Muss dokumentiert werden"}, {"text": "Serverleistung", "correct": false, "because": "Kein Datenschutzfaktor"}, {"text": "Typografie", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Verzeichnis ist für die DSGVO-Nachweispflicht. b) Es ist nur für große Unternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle mit Risiko"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht im Verzeichnis?', 4, '[{"text": "Zweck der Verarbeitung", "correct": false, "because": "Pflichtangabe"}, {"text": "Sicherheitsmaßnahmen", "correct": false, "because": "Muss enthalten sein"}, {"text": "Visuelle Gestaltung", "correct": true, "because": "Kein DSGVO-Anforderung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss das Verzeichnis öffentlich sein?', 2, '[{"text": "Nein", "correct": true, "because": "Intern, aber Behörden zugänglich"}, {"text": "Ja", "correct": false, "because": "Nicht öffentlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prozesse müssen im Verzeichnis dokumentiert werden?', 4, '[{"text": "Datenverarbeitungsvorgänge", "correct": true, "because": "Kern der DSGVO"}, {"text": "Datenempfänger", "correct": true, "because": "Muss angegeben werden"}, {"text": "Hardware-Spezifikationen", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Verzeichnis nur für Behörden ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für interne Kontrolle"}, {"text": "Ja", "correct": false, "because": "Dient mehreren Zwecken"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Verzeichnis?', 3, '[{"text": "Vollständigkeit", "correct": true, "because": "Alle Tätigkeiten erfassen"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Design", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Verzeichnis muss aktualisiert werden. b) Es ist nur einmalig nötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Änderungen erfordern Updates"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Informationen sind im Verzeichnis zwingend?', 5, '[{"text": "Verantwortlicher", "correct": true, "because": "Pflicht gemäß DSGVO"}, {"text": "Löschfristen", "correct": true, "because": "Zeigt Speicherbegrenzung"}, {"text": "Farbanpassung", "correct": false, "because": "Nicht erforderlich"}, {"text": "Serverstandort", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Verzeichnis unwichtig?', 3, '[{"text": "Datenkategorien", "correct": false, "because": "Muss dokumentiert werden"}, {"text": "Zweckangabe", "correct": false, "because": "Pflichtfeld"}, {"text": "Animationseffekte", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss das Verzeichnis digital sein?', 3, '[{"text": "Nein", "correct": true, "because": "Kann auch analog sein"}, {"text": "Ja", "correct": false, "because": "Form nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Verzeichnis bei Audits geprüft wird?', 2, '[{"text": "Ja", "correct": true, "because": "Behörden können es einsehen"}, {"text": "Nein", "correct": false, "because": "Nachweispflicht gilt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für ein vollständiges Verzeichnis?', 4, '[{"text": "Technische Sicherheitsmaßnahmen", "correct": true, "because": "Schutz dokumentieren"}, {"text": "Zufällige Daten", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Grafische Darstellung", "correct": false, "because": "Kein Fokus"}]');
